mapper.select:
select c.id id, c.cul_num culNum, c.cul_name culName, c.sort sort, f.file_url culUrl, c.cul_desc culDesc, c.status status, c.art_type artType, c.link_url, c.publish_date publishDate from t_portal_carousel c left join t_base_file f on c.cul_url_id = f.id and f.is_valid = 1 where c.is_valid=1
and c.school_id = #{query.schoolId}
and ( c.cul_name like concat('%', #{query.keyword}, '%') or c.cul_num like concat('%', #{query.keyword}, '%') )
and c.status = #{query.status}
and c.art_type = #{query.artType}
and ( c.cul_name like concat('%', #{query.culName}, '%') )
and c.publish_date > #{query.startTime} and c.publish_date < #{query.endTime}
order by c.sort asc, c.create_time desc

select c.id id, c.cul_num culNum, c.cul_name culName, c.sort sort, f.file_url culUrl, c.cul_desc culDesc, c.status status, c.art_type artType, c.link_url, c.publish_date publishDate from t_portal_carousel c,t_base_file f where c.cul_url_id = f.id and c.is_valid=1
and c.id = #{query.id}
and c.cul_num = #{query.culNum}
